namespace sv_e31a1c473c1c4a92ac635d6f98bf5325.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

using sv_e31a1c473c1c4a92ac635d6f98bf5325.Models;

namespace sv_e31a1c473c1c4a92ac635d6f98bf5325.Services;

public class ApplicationService : IApplicationService
{
    public async Task<int> SubmitApplicationAsync(JobApplication application)
    {
        await Task.Delay(1000); // Simulate network call
        return Random.Shared.Next(10000, 99999);
    }

    public async Task<bool> ValidateEmailAsync(string email)
    {
        await Task.Delay(300); // Simulate validation
        return !string.IsNullOrWhiteSpace(email) && email.Contains('@') && email.Contains('.');
    }
}

@namespace sv_e31a1c473c1c4a92ac635d6f98bf5325.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var status = GetStepStatus(stepIndex);
            <li class="step-item @status" @onclick="() => OnStepClick(stepIndex)">
                <span class="step-circle">
                    @if (status == "completed")
                    {
                        <span class="checkmark">&#10003;</span>
                    }
                    else
                    {
                        @(stepIndex + 1)
                    }
                </span>
                <span class="step-label">@StepNames[stepIndex]</span>
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public IReadOnlyList<string> StepNames { get; set; } = [];
    [Parameter, EditorRequired] public IReadOnlySet<int> CompletedSteps { get; set; } = new HashSet<int>();
    [Parameter] public EventCallback<int> OnNavigateToStep { get; set; }

    private string GetStepStatus(int index)
    {
        if (index == CurrentStep) return "active";
        if (CompletedSteps.Contains(index)) return "completed";
        return "future";
    }

    private async Task OnStepClick(int index)
    {
        if (CompletedSteps.Contains(index))
        {
            await OnNavigateToStep.InvokeAsync(index);
        }
    }
}

@namespace sv_e31a1c473c1c4a92ac635d6f98bf5325.Components.Pages.Apply

<div class="step-content">
    <h2>Personal Information</h2>

    <div class="form-group">
        <label for="fullName">Full Name *</label>
        <input id="fullName" type="text" @bind="FullName" @bind:event="oninput" class="form-control" />
    </div>

    <div class="form-group">
        <label for="email">Email *</label>
        <input id="email" type="email" @bind="Email" @bind:event="oninput" class="form-control" />
        @if (!string.IsNullOrEmpty(_emailError))
        {
            <span class="field-error">@_emailError</span>
        }
    </div>

    <div class="form-group">
        <label for="phone">Phone *</label>
        <input id="phone" type="tel" @bind="Phone" @bind:event="oninput" class="form-control" />
    </div>

    <div class="form-group">
        <label for="address">Address *</label>
        <input id="address" type="text" @bind="Address" @bind:event="oninput" class="form-control" />
    </div>

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="validation-summary">@_validationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-primary" @onclick="HandleNext" disabled="@_isValidating">
            @(_isValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public EventCallback<(string FullName, string Email, string Phone, string Address)> OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private string _validationError = "";
    private string _emailError = "";
    private bool _isValidating;

    private async Task HandleNext()
    {
        _validationError = "";
        _emailError = "";

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
            string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            _validationError = "All fields are required.";
            return;
        }

        if (ValidateEmail is not null)
        {
            _isValidating = true;
            StateHasChanged();
            var isValid = await ValidateEmail(Email);
            _isValidating = false;

            if (!isValid)
            {
                _emailError = "Please enter a valid email address.";
                return;
            }
        }

        await OnNext.InvokeAsync((FullName, Email, Phone, Address));
    }
}

@namespace sv_e31a1c473c1c4a92ac635d6f98bf5325.Components.Pages.Apply

<div class="work-entry-card">
    <div class="work-entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button class="btn btn-danger-sm" @onclick="() => OnRemove.InvokeAsync(Index)">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Company" @oninput="e => OnFieldChanged(nameof(Company), e.Value?.ToString() ?? "")" class="form-control" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Title" @oninput="e => OnFieldChanged(nameof(Title), e.Value?.ToString() ?? "")" class="form-control" />
    </div>

    <div class="form-row">
        <div class="form-group half">
            <label>Start Date *</label>
            <input type="date" value="@StartDate.ToString("yyyy-MM-dd")" @onchange="e => OnStartDateChanged(e.Value?.ToString() ?? "")" class="form-control" />
        </div>
        <div class="form-group half">
            <label>End Date</label>
            <input type="date" value="@(EndDate?.ToString("yyyy-MM-dd") ?? "")" @onchange="e => OnEndDateChanged(e.Value?.ToString() ?? "")" class="form-control" disabled="@IsCurrent" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="e => OnIsCurrentChanged((bool)(e.Value ?? false))" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea value="@Description" @oninput="e => OnFieldChanged(nameof(Description), e.Value?.ToString() ?? "")" class="form-control" rows="3"></textarea>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<int> OnRemove { get; set; }
    [Parameter] public EventCallback<(int Index, string Field, object Value)> OnEntryChanged { get; set; }

    private void OnFieldChanged(string field, string value)
    {
        OnEntryChanged.InvokeAsync((Index, field, value));
    }

    private void OnStartDateChanged(string value)
    {
        if (DateTime.TryParse(value, out var date))
            OnEntryChanged.InvokeAsync((Index, nameof(StartDate), date));
    }

    private void OnEndDateChanged(string value)
    {
        if (DateTime.TryParse(value, out var date))
            OnEntryChanged.InvokeAsync((Index, nameof(EndDate), (object)date));
    }

    private void OnIsCurrentChanged(bool value)
    {
        OnEntryChanged.InvokeAsync((Index, nameof(IsCurrent), value));
    }
}

@namespace sv_e31a1c473c1c4a92ac635d6f98bf5325.Components.Pages.Apply

<div class="step-content">
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var entry = Entries[i];
        <WorkEntryForm Index="@i"
                       Company="@entry.Company"
                       Title="@entry.Title"
                       StartDate="@entry.StartDate"
                       EndDate="@entry.EndDate"
                       Description="@entry.Description"
                       IsCurrent="@entry.IsCurrent"
                       CanRemove="@(Entries.Count > 1)"
                       OnRemove="HandleRemove"
                       OnEntryChanged="HandleEntryChanged" />
    }

    <button class="btn btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="validation-summary">@_validationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntryModel> Entries { get; set; } = [];
    [Parameter] public EventCallback<List<WorkEntryModel>> OnEntriesChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string _validationError = "";

    private async Task AddEntry()
    {
        Entries.Add(new WorkEntryModel());
        await OnEntriesChanged.InvokeAsync(Entries);
    }

    private async Task HandleRemove(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
            await OnEntriesChanged.InvokeAsync(Entries);
        }
    }

    private async Task HandleEntryChanged((int Index, string Field, object Value) args)
    {
        var entry = Entries[args.Index];
        switch (args.Field)
        {
            case "Company": entry.Company = (string)args.Value; break;
            case "Title": entry.Title = (string)args.Value; break;
            case "StartDate": entry.StartDate = (DateTime)args.Value; break;
            case "EndDate": entry.EndDate = (DateTime)args.Value; break;
            case "Description": entry.Description = (string)args.Value; break;
            case "IsCurrent":
                entry.IsCurrent = (bool)args.Value;
                if (entry.IsCurrent) entry.EndDate = null;
                break;
        }
        await OnEntriesChanged.InvokeAsync(Entries);
    }

    private async Task HandleNext()
    {
        _validationError = "";
        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                _validationError = "Each position requires at least a company name and job title.";
                return;
            }
        }
        await OnNext.InvokeAsync();
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public string Description { get; set; } = "";
        public bool IsCurrent { get; set; }
    }
}

