@namespace sv_e31a1c473c1c4a92ac635d6f98bf5325.Components.Pages.Apply

<div class="step-content">
    <h2>References</h2>
    <p class="step-description">Please provide 2-3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var refModel = References[i];
        <ReferenceForm Index="@i"
                       Name="@refModel.Name"
                       Relationship="@refModel.Relationship"
                       Email="@refModel.Email"
                       Phone="@refModel.Phone"
                       CanRemove="@(References.Count > 2)"
                       OnRemove="HandleRemove"
                       OnFieldChanged_Callback="HandleFieldChanged" />
    }

    @if (References.Count < 3)
    {
        <button class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="validation-summary">@_validationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = [];
    [Parameter] public EventCallback<List<ReferenceModel>> OnReferencesChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string _validationError = "";

    private async Task AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceModel());
            await OnReferencesChanged.InvokeAsync(References);
        }
    }

    private async Task HandleRemove(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
            await OnReferencesChanged.InvokeAsync(References);
        }
    }

    private async Task HandleFieldChanged((int Index, string Field, string Value) args)
    {
        var refModel = References[args.Index];
        switch (args.Field)
        {
            case "Name": refModel.Name = args.Value; break;
            case "Relationship": refModel.Relationship = args.Value; break;
            case "Email": refModel.Email = args.Value; break;
            case "Phone": refModel.Phone = args.Value; break;
        }
        await OnReferencesChanged.InvokeAsync(References);
    }

    private async Task HandleNext()
    {
        _validationError = "";
        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                _validationError = "All reference fields are required.";
                return;
            }
        }
        await OnNext.InvokeAsync();
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

@namespace sv_e31a1c473c1c4a92ac635d6f98bf5325.Components.Pages.Apply

<div class="step-content">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label for="coverLetter">Write your cover letter</label>
        <textarea id="coverLetter" class="form-control cover-letter-textarea"
                  @bind="CoverLetter" @bind:event="oninput"
                  maxlength="2000" rows="12"
                  placeholder="Tell us why you're a great fit for this role..."></textarea>
        <span class="char-count @(CoverLetter.Length > 1800 ? "char-count-warning" : "")">
            @CoverLetter.Length / 2000 characters
        </span>
    </div>

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="validation-summary">@_validationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<string> CoverLetterChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string _validationError = "";

    private async Task HandleNext()
    {
        _validationError = "";
        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            _validationError = "Please write a cover letter before continuing.";
            return;
        }
        await CoverLetterChanged.InvokeAsync(CoverLetter);
        await OnNext.InvokeAsync();
    }
}

@namespace sv_e31a1c473c1c4a92ac635d6f98bf5325.Components.Pages.Apply

<div class="step-content">
    <h2>Review & Submit</h2>

    @if (_submitted)
    {
        <div class="submission-confirmation">
            <h3>&#10003; Application Submitted!</h3>
            <p>Your application has been received. Your application ID is:</p>
            <p class="application-id">#@_applicationId</p>
        </div>
    }
    else
    {
        <div class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
            </div>
            <dl class="review-data">
                <dt>Name</dt><dd>@FullName</dd>
                <dt>Email</dt><dd>@Email</dd>
                <dt>Phone</dt><dd>@Phone</dd>
                <dt>Address</dt><dd>@Address</dd>
            </dl>
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
