{"path": "/tmp/sv-e31a1c473c1c4a92ac635d6f98bf5325/Components/Pages/Apply/WorkHistoryStep.razor", "file_text": "@namespace sv_e31a1c473c1c4a92ac635d6f98bf5325.Components.Pages.Apply

<div class="step-content">
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var entry = Entries[i];
        <WorkEntryForm Index="@i"
                       Company="@entry.Company"
                       Title="@entry.Title"
                       StartDate="@entry.StartDate"
                       EndDate="@entry.EndDate"
                       Description="@entry.Description"
                       IsCurrent="@entry.IsCurrent"
                       CanRemove="@(Entries.Count > 1)"
                       OnRemove="HandleRemove"
                       OnEntryChanged="HandleEntryChanged" />
    }

    <button class="btn btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="validation-summary">@_validationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntryModel> Entries { get; set; } = [];
    [Parameter] public EventCallback<List<WorkEntryModel>> OnEntriesChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string _validationError = "";

    private async Task AddEntry()
    {
        Entries.Add(new WorkEntryModel());
        await OnEntriesChanged.InvokeAsync(Entries);
    }

    private async Task HandleRemove(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
            await OnEntriesChanged.InvokeAsync(Entries);
        }
    }

    private async Task HandleEntryChanged((int Index, string Field, object Value) args)
    {
        var entry = Entries[args.Index];
        switch (args.Field)
        {
            case "Company": entry.Company = (string)args.Value; break;
            case "Title": entry.Title = (string)args.Value; break;
            case "StartDate": entry.StartDate = (DateTime)args.Value; break;
            case "EndDate": entry.EndDate = (DateTime)args.Value; break;
            case "Description": entry.Description = (string)args.Value; break;
            case "IsCurrent":
                entry.IsCurrent = (bool)args.Value;
                if (entry.IsCurrent) entry.EndDate = null;
                break;
        }
        await OnEntriesChanged.InvokeAsync(Entries);
    }

    private async Task HandleNext()
    {
        _validationError = "";
        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                _validationError = "Each position requires at least a company name and job title.";
                return;
            }
        }
        await OnNext.InvokeAsync();
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public string Description { get; set; } = "";
        public bool IsCurrent { get; set; }
    }
}
"}

