@namespace sv_e31a1c473c1c4a92ac635d6f98bf5325.Components.Pages.Apply

<div class="reference-card">
    <div class="reference-header">
        <h4>Reference @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button class="btn btn-danger-sm" @onclick="() => OnRemove.InvokeAsync(Index)">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Name *</label>
        <input type="text" value="@Name" @oninput="e => OnFieldChanged(nameof(Name), e.Value?.ToString() ?? "")" class="form-control" />
    </div>

    <div class="form-group">
        <label>Relationship *</label>
        <input type="text" value="@Relationship" @oninput="e => OnFieldChanged(nameof(Relationship), e.Value?.ToString() ?? "")" class="form-control" />
    </div>

    <div class="form-row">
        <div class="form-group half">
            <label>Email *</label>
            <input type="email" value="@Email" @oninput="e => OnFieldChanged(nameof(Email), e.Value?.ToString() ?? "")" class="form-control" />
        </div>
        <div class="form-group half">
            <label>Phone *</label>
            <input type="tel" value="@Phone" @oninput="e => OnFieldChanged(nameof(Phone), e.Value?.ToString() ?? "")" class="form-control" />
        </div>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Name { get; set; } = "";
    [Parameter] public string Relationship { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<int> OnRemove { get; set; }
    [Parameter] public EventCallback<(int Index, string Field, string Value)> OnFieldChanged_Callback { get; set; }

    private void OnFieldChanged(string field, string value)
    {
        OnFieldChanged_Callback.InvokeAsync((Index, field, value));
    }
}

@namespace sv_e31a1c473c1c4a92ac635d6f98bf5325.Components.Pages.Apply

<div class="step-content">
    <h2>References</h2>
    <p class="step-description">Please provide 2-3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var refModel = References[i];
        <ReferenceForm Index="@i"
                       Name="@refModel.Name"
                       Relationship="@refModel.Relationship"
                       Email="@refModel.Email"
                       Phone="@refModel.Phone"
                       CanRemove="@(References.Count > 2)"
                       OnRemove="HandleRemove"
                       OnFieldChanged_Callback="HandleFieldChanged" />
    }

    @if (References.Count < 3)
    {
        <button class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="validation-summary">@_validationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = [];
