@namespace sv_e31a1c473c1c4a92ac635d6f98bf5325.Components.Pages.Apply

<div class="step-content">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label for="coverLetter">Write your cover letter</label>
        <textarea id="coverLetter" class="form-control cover-letter-textarea"
                  @bind="CoverLetter" @bind:event="oninput"
                  maxlength="2000" rows="12"
                  placeholder="Tell us why you're a great fit for this role..."></textarea>
        <span class="char-count @(CoverLetter.Length > 1800 ? "char-count-warning" : "")">
            @CoverLetter.Length / 2000 characters
        </span>
    </div>

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="validation-summary">@_validationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
