.step-label {
    font-size: 0.75rem;
    text-align: center;
    color: #999;
}

.step-item.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #198754;
}

.checkmark {
    font-size: 1rem;
}

